class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_bind_link(self, setup, dut, misc, role):
        """Resolve `[misc] ck_link_<role>` on THIS bench, bind it, and assert its media.

        Fixed frame — do not edit or delete. Three failures it converts from silent to loud:
          1. an undeclared role: the bench has not agreed to host this test;
          2. `init_portlink()` returning (None, None) for a link the bench does not have —
             a None port later renders as `interface None`, so the run fails looking like a
             SCRIPT defect;
          3. the bound port being the wrong MEDIA. That one cannot be caught offline: media
             belongs to the pluggable, and the CLI accepts `polarity`/`speed 100` on fibre
             where they are meaningless, so the run would report a PRODUCT failure that is
             really a cabling error.
        Raising aborts the suite on purpose: "this bench cannot host this test" is not a
        test result. See ask-ck/pytest-create/TOPOLOGY-PROFILES.md.
        """
        import ck_media
        ref = misc.get('ck_link_' + role)
        if not ref:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: this .setup declares no "
                "ck_link_%s, so the %s link this test needs is not available here. "
                "See TOPOLOGY-PROFILES.md." % (role, role))
        dev_a, dev_b, _named_port = ck_media.parse_link_ref(ref)
        dut_key = misc.get('ck_role_dut', 'swi_a')
        far_key = dev_b if dev_a == dut_key else dev_a
        far = setup.init_swi(far_key)
        (near_port, far_port) = setup.init_portlink(dut, far, type1='port', type2='port')
        if near_port is None or far_port is None:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: ck_link_%s = %r but no unused "
                "matching [portlink] exists between %s and %s." % (role, ref, dut_key, far_key))
        status = dut.cmd('show interface %s status' % near_port.name)
        ok, why = ck_media.assert_role_media(status, near_port.name, role)
        if not ok:
            raise RuntimeError(why)
        self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
            role, dut_key, near_port.name, far_key, far_port.name, why))
        return near_port, far_port, far

    def init(self, setup):
        # Topology is resolved from the .setup [misc] ROLE CONTRACT at run time, so this
        # script names no device and no port: it binds correctly on any bench that declares
        # the roles it needs, and fails loudly on one that does not. The role names come
        # from TOPOLOGY-PROFILES.md; the bench says what they mean HERE.
        tb = setup.init_tb()
        misc = setup.get_all_misc()
        dutA = setup.init_swi(misc.get('ck_role_dut', 'swi_a'))
        
        stk_a = setup.init_stk('stk_a')
        self.tb = tb
        self.dutA = dutA
        self.stk_a = stk_a
        # Bind the ONE link this case needs from the bench's role contract, assert its media,
        # and take the PARTNER from that link's far end — no second lookup. Deterministic on
        # purpose: this used to be a FILL slot, and the model declared links the test never
        # used (T33235 bound 4 devices and 2 links while referencing 1 of each, so the script
        # demanded cabling for no reason). One link => exactly one partner.
        (dutA.portA, self.ck_far_port, dut) = self._ck_bind_link(
            setup, dutA, misc, 'copper')
        self.dut = dut
        # Cases 13, 23 and 24 exercise PER-PORT independence and the per-port MIB, which by
        # definition need a SECOND DUT transmit port and its own link. That is a real topology
        # demand, so it is bound here (a second copper link to the same partner) and fails
        # loudly on a bench that cannot host it — rather than those cases reading an unbound
        # dut.portB / tb.ethB attribute that would later render as `interface None`.
        (dutA.portB, self.ck_far_port_b, _far_b) = self._ck_bind_link(
            setup, dutA, misc, 'copper')
        self.dut.portB = self.ck_far_port_b
        # A test binds the DUT plus the partner(s) at the far end of each link it actually
        # uses. Needing a further partner means declaring a further link role in
        # TOPOLOGY-PROFILES.md, not guessing a device here.

    def configure(self):
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # ART 1332_lldp_med/test-1332.1001.py lines 8-41
        dutA = self.dutA
        dut  = self.dut
        tb   = self.tb
        portA       = dutA.portA          # test port on the DUT (bound by the fixed init frame)
        partnerPort = dut.portA           # partner switch port facing the DUT

        # Enable LLDP globally on the DUT and set the test port to transmit and receive.
        dutA.mode(')#')
        dutA.cmd('lldp run')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp transmit')
        dutA.cmd('lldp receive')
        dutA.mode('#')

        # Configure the partner switch to receive LLDP so it records neighbour information.
        dut.mode(')#')
        dut.cmd('lldp run')
        dut.cmd('interface {}'.format(partnerPort.name))
        dut.cmd('lldp receive')
        dut.mode('#')

        # Bring up the physical link from the test port to the partner switch, and the
        # testbox interface used to capture transmitted LLDPDUs (per-test tcpdump start/stop
        # is driven from each test case, e.g. tb.start_tcpdump(tb.ethA.name, ...)).
        portA.up()
        partnerPort.up()
        tb.ethA.up()

    def tear_down(self):
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dutA = self.dutA
        dut  = self.dut
        portA       = dutA.portA
        partnerPort = dut.portA

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no lldp transmit')
        dutA.cmd('no lldp receive')
        dutA.cmd('exit')
        dutA.cmd('no lldp run')
        dutA.mode('#')

        dut.mode(')#')
        dut.cmd('interface {}'.format(partnerPort.name))
        dut.cmd('no lldp receive')
        dut.cmd('exit')
        dut.cmd('no lldp run')
        dut.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = 'On the test port select only the port-description optional TLV (`lldp tlv-select port-description`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = 'On the test port select only the port-description optional TLV (`lldp tlv-select port-description`). | verify: `show lldp interface <port>` lists port-description as an enabled/selected TLV, and a captured LLDPDU from the test port decodes a Port Description TLV.'

    def main(self):
        # ART 1331_past_issues/test-1331.1001.py lines 760-784
        self.log('STEP 1: On the test port select only the port-description optional TLV (`lldp tlv-select port-description`).')
        dut = self.testSet.dut
        dutA = self.testSet.dutA
        tb = self.testSet.tb
        port = dut.portA
        ethA = tb.ethA

        # Select only the port-description optional TLV on the test port
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('lldp tlv-select port-description')
        dutA.mode('#')

        # CLI observation: what TLVs are enabled for Tx on the test port
        cli = dutA.cmd('show lldp interface {}'.format(port.name))
        self.log(cli)

        # Capture an LLDPDU transmitted by the DUT on the test port. LLDPDUs are sent to
        # the LLDP multicast MAC; wait at least one Tx timer interval (30s default) for one.
        subProc = tb.start_tcpdump(ethA.name, '%s_%s.pcap' % (self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        # Decode captured LLDPDUs and look for a Port Description TLV (TLV type 4).
        # lldp_basic covers the mandatory chassis/port/ttl TLVs; optional TLVs follow in
        # the payload as {7-bit type, 9-bit length} headers.
        pd_decoded = False
        for pkt in recPktList:
            if not pkt.haslayer(lldp_basic):
                continue
            raw = bytes(pkt[lldp_basic].payload)
            idx = 0
            while idx + 2 <= len(raw):
                header = (raw[idx] << 8) | raw[idx + 1]
                tlv_type = header >> 9
                tlv_len = header & 0x1FF
                if tlv_type == 0:  # End Of LLDPDU TLV
                    break
                if tlv_type == 4:  # Port Description TLV
                    pd_decoded = True
                    self.log('Decoded Port Description TLV from a captured LLDPDU')
                idx += 2 + tlv_len
            if pd_decoded:
                break

        # Pick the CLI row for our port; the enabled Base TLVs are abbreviated (Pd = Port Description).
        pd_row = next((l for l in cli.splitlines() if l.split()[:1] == [port.name]), None)
        output = 'show lldp interface row: {} | Port Description TLV decoded from capture: {}'.format(pd_row, pd_decoded)
        self.log('OBSERVED: {}'.format(output))

        if pd_row is None:
            self.failed('port {} missing from show lldp interface output'.format(port.name))
        elif 'Pd' in pd_row and pd_decoded:
            self.passed('{}: port-description (Pd) listed as an enabled TLV in show lldp interface and a Port Description TLV decoded from the captured LLDPDU'.format(port.name))
        elif 'Pd' not in pd_row:
            self.failed('{}: port-description (Pd) not listed as an enabled Tx TLV in show lldp interface: {}'.format(port.name, pd_row))
        else:
            self.failed('{}: port-description enabled in CLI but no Port Description TLV decoded in any captured LLDPDU'.format(port.name))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        dutA = self.testSet.dutA
        port = self.testSet.dut.portA
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('no lldp tlv-select port-description')
        dutA.mode('#')


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = 'On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = 'On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`). | verify: `show lldp interface <port>` shows system-name selected, and a captured LLDPDU decodes a System Name TLV.'

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 283-295
        self.log('STEP 2: On the test port additionally select the system-name optional TLV (`lldp tlv-select system-name`).')
        dutA = self.testSet.dutA
        dut = self.testSet.dut
        tb = self.testSet.tb
        ethA = tb.ethA
        port = dut.portA

        # Select the system-name optional Base TLV on the test port
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('lldp tlv-select system-name')
        dutA.mode('#')

        # (1) CLI: the port's row of `show lldp interface` must list System Name (Sn)
        #     among the Base TLVs Enabled for Tx. Match the port ROW, not the legend
        #     (the legend always spells out 'Sn = System Name', so a bare substring
        #     test on the whole output is a false green).
        cli = dutA.cmd('show lldp interface {}'.format(port.name))
        self.log(cli)
        row = next((l for l in cli.splitlines() if l.split()[:1] == [port.name]), None)
        cli_selected = row is not None and 'Sn' in row

        # (2) Capture an LLDPDU the DUT transmits out the test port and decode it,
        #     then confirm a System Name TLV (LLDP TLV type 5) is present in it.
        subProc = tb.start_tcpdump(ethA.name, '%s_%s.pcap' % (self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e')
        # Default LLDP transmit interval is 30s; wait long enough for one advertisement.
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        def decode_system_name_tlv(pkt):
            # Walk the LLDPDU TLV chain (2-byte header: top 7 bits = type, low 9 = len).
            data = bytes(pkt)[14:]
            i = 0
            while i + 2 <= len(data):
                hdr = (data[i] << 8) | data[i + 1]
                ttype = hdr >> 9
                tlen = hdr & 0x1FF
                if ttype == 0:
                    break
                if ttype == 5:
                    return data[i + 2:i + 2 + tlen]
                i += 2 + tlen
            return None

        decoded_count = 0
        system_name = None
        for idx, pkt in enumerate(recPktList):
            if pkt.haslayer(lldp_basic):
                decoded_count += 1
                self.log('Packet %d decodes as an LLDPDU: %s' % (idx + 1, pkt.layers()))
                sn = decode_system_name_tlv(pkt)
                if sn is not None:
                    system_name = sn.decode('utf-8', 'replace')
                    self.log('System Name TLV decoded in packet %d: "%s"' % (idx + 1, system_name))
                    break

        system_name_seen = system_name is not None
        output = 'show-lldp Sn selected=%s ; LLDPDUs decoded=%d ; System Name TLV=%s' % (
            cli_selected, decoded_count, system_name)
        self.log('OBSERVED: {}'.format(output))

        if cli_selected and system_name_seen:
            self.passed('show lldp interface %s lists System Name (Sn) and a captured LLDPDU decodes a System Name TLV ("%s")' % (port.name, system_name))
        elif row is None:
            self.failed('port %s not found in `show lldp interface` output' % (port.name))
        elif not cli_selected:
            self.failed('System Name (Sn) not listed as an enabled Base TLV for %s: row=%r' % (port.name, row))
        else:
            self.failed('no System Name TLV decoded in any of the %d captured LLDPDUs from %s' % (len(recPktList), port.name))

    def tear_down(self):
        # Deselect the system-name TLV so the next case starts clean. No pass/fail.
        dutA = self.testSet.dutA
        port = self.testSet.dut.portA
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('no lldp tlv-select system-name')
        dutA.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = 'On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = 'On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`). | verify: `show lldp interface <port>` shows system-description selected, and a captured LLDPDU decodes a System Description TLV.'

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 270-282
        self.log('STEP 3: On the test port additionally select the system-description optional TLV (`lldp tlv-select system-description`).')
        dut = self.testSet.dut
        dutA = self.testSet.dutA
        tb = self.testSet.tb
        ethA = tb.ethA
        port = dut.portA
        name = port.name

        # Select the system-description optional Base TLV on the test port
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(name))
        dutA.cmd('lldp tlv-select system-description')
        dutA.mode('#')

        # Capture an LLDPDU transmitted by the DUT on the test port (LLDP tx on config change)
        subProc = tb.start_tcpdump(ethA.name, '%s_%s.pcap' % (self.testCaseName, ethA), 'ether dst 01:80:c2:00:00:0e and not ether src 00:00:00:00:00:01')
        time.sleep(35)
        recPktList = tb.stop_tcpdump(subProc)

        cli = dutA.cmd('show lldp interface {}'.format(name))
        self.log(cli)

        # The port's own data row must list Sd (System Description) as a Base TLV enabled for Tx.
        # The abbreviation legend line also contains 'Sd', so match the port row by first token only.
        row = next((l for l in cli.splitlines() if l.split()[:1] == [name]), None)
        cli_selected = row is not None and 'Sd' in row.split()

        # Decode captured LLDPDUs; walk the raw TLV stream for the System Description TLV (base type 6).
        lldp_decoded = False
        sysdesc_found = False
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                lldp_decoded = True
                self.log('Decoded LLDPDU: chassis_id=%s port_id=%s ttl=%s' % (
                    pkt[lldp_basic].chassis_id, pkt[lldp_basic].port_id, pkt[lldp_basic].ttl_val))
                lldp = bytes(pkt)[14:]
                i = 0
                while i + 2 <= len(lldp):
                    hdr = (lldp[i] << 8) | lldp[i + 1]
                    ttype = hdr >> 9
                    tlen = hdr & 0x1ff
                    if ttype == 0:
                        break
                    if ttype == 6:
                        sysdesc_found = True
                        break
                    i += 2 + tlen
                if sysdesc_found:
                    break

        output = 'port {} row Sd selected={}, LLDPDUs captured={}, decoded={}, System Description TLV present={}'.format(
            name, cli_selected, len(recPktList), lldp_decoded, sysdesc_found)
        self.log('OBSERVED: {}'.format(output))

        if row is None:
            self.failed('port {} not found in show lldp interface output'.format(name))
        elif not cli_selected:
            self.failed('show lldp interface {} does not list Sd (System Description) for the port: {}'.format(name, row))
        elif not lldp_decoded:
            self.failed('no LLDPDU from {} was captured/decoded to verify the System Description TLV'.format(name))
        elif not sysdesc_found:
            self.failed('captured LLDPDU from {} did not decode a System Description TLV (type 6)'.format(name))
        else:
            self.passed('show lldp interface {} lists Sd and the captured LLDPDU decodes a System Description TLV'.format(name))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        dutA = self.testSet.dutA
        port = self.testSet.dut.portA
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(port.name))
        dutA.cmd('no lldp tlv-select system-description')
        dutA.mode('#')


class TestCase_4(ATTestCase.TestCase):
    testCaseDesc = 'On the test port additionally select the system-capabilities optional TLV (`lldp tlv-select system-capabilities`).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = 'On the test port additionally select the system-capabilities optional TLV (`lldp tlv-select system-capabilities`). | verify: `show lldp interface <port>` shows system-capabilities selected, and a captured LLDPDU decodes a System Capabilities TLV.'

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 102-136
        self.log('STEP 4: On the test port additionally select the system-capabilities optional TLV (`lldp tlv-select system-capabilities`).')
        dutA = self.testSet.dutA
        dut = self.testSet.dut
        tb = self.testSet.tb
        ethA = tb.ethA
        portA = dut.portA

        # Select the System Capabilities optional Base TLV on the test port.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('lldp tlv-select system-capabilities')
        dutA.mode('#')

        # Capture the DUT's transmitted LLDPDUs while the CLI is queried.
        subProc = tb.start_tcpdump(ethA.name, '{}_{}.pcap'.format(self.testCaseName, ethA),
                                   'ether dst 01:80:c2:00:00:0e and not ether src 00:00:00:00:00:01')
        # Allow at least one LLDP transmit interval to elapse.
        time.sleep(35)
        output = dutA.cmd('show lldp interface {}'.format(portA.name))
        self.log(output)
        recPktList = tb.stop_tcpdump(subProc)
        self.log('OBSERVED: {}'.format(output))

        # Decode the captured LLDPDUs; the base System Capabilities TLV is lldp_base_cap_tlv.
        cap_found = False
        for idx, pkt in enumerate(recPktList):
            if pkt.haslayer(lldp_basic) and pkt.haslayer(lldp_base_cap_tlv):
                self.log('Packet {} carries a System Capabilities (base capabilities) TLV'.format(idx + 1))
                cap_found = True

        # The show output lists selected Base TLVs by abbreviation; Sc = System Capabilities.
        row = next((l for l in output.splitlines() if l.split()[:1] == [portA.name]), None)

        if row is None:
            self.failed('port {} missing from "show lldp interface" output'.format(portA.name))
        elif 'Sc' not in row:
            self.failed('system-capabilities (Sc) not selected on {} in show lldp interface: {}'.format(portA.name, row.strip()))
        elif len(recPktList) == 0:
            self.failed('no LLDPDUs captured from {} - cannot confirm System Capabilities TLV'.format(portA.name))
        elif not cap_found:
            self.failed('captured LLDPDU from {} does not decode a System Capabilities TLV'.format(portA.name))
        else:
            self.passed('{} shows system-capabilities (Sc) selected and a captured LLDPDU decodes a System Capabilities TLV'.format(portA.name))

