    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = "Associate a second management address with the port (configure an additional management address using the device's documented management-address command), then capture LLDPDUs from the test port. | verify: A single captured LLDPDU carries multiple Management Address TLVs, one per configured management address."

    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 296-308
        self.log("STEP 10: Associate a second management address with the port (configure an additional management address using the device's documented management-address command), then capture LLDPDUs from the test port.")
        dutA = self.testSet.dutA
        dut = self.testSet.dut
        tb = self.testSet.tb
        ethA = tb.ethA
        portA = dut.portA

        # Associate a second management address using the documented management-address
        # command so the DUT advertises more than one address in its LLDPDUs.
