        maxManTlvs = 0
        for pkt in recPktList:
            if pkt.haslayer(lldp_basic):
                manCount = 0
                idx = 1
                while pkt.getlayer(lldp_man_tlv, idx) is not None:
                    manCount += 1
                    idx += 1
                if manCount > maxManTlvs:
                    maxManTlvs = manCount

        output = '{} LLDPDUs captured; max Management Address TLVs in a single LLDPDU = {}'.format(len(recPktList), maxManTlvs)
