    def main(self):
        # legacy 5003_feature_limits/test-5003.0014-LLDP/lldp_class.py lines 283-295
        self.log('STEP 16: Clear only the system-name TLV on the test port (`no lldp tlv-select system-name`), leaving the remaining optional TLVs selected, and capture LLDPDUs.')
        dutA = self.testSet.dutA
