class TestCase_31(ATTestCase.TestCase):
    testCaseDesc = 'Attempt to select a TLV using an out-of-range value where the command takes a numeric/index argument (a value outside the documented range).'
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = 'Attempt to select a TLV using an out-of-range value where the command takes a numeric/index argument (a value outside the documented range). | verify: The CLI rejects the command with a diagnostic/error message and applies no change.'

    def main(self):
        # ART 1337_cli_walk/test-1337.1.py lines 586-643
        self.log('STEP 31: Attempt to select a TLV using an out-of-range value where the command takes a numeric/index argument (a value outside the documented range).')
        dut = self.testSet.dut
        port = dut.portA                      # a SwitchPort the fixed init() frame bound
        # The LLDP-MED location TLV is selected by a civic-location identifier whose
        # documented range is 1-4095; drive an index well outside that range on the test
        # port and capture the CLI's response verbatim.
        badIndex = '999999'
        dut.mode(')#')
        dut.cmd('interface {}'.format(port.name))
        output = dut.cmd('location civic-location identifier {}'.format(badIndex))
        dut.mode('#')                         # back to exec before any `show`
        self.log('OBSERVED: {}'.format(output))
        # Prove no change was applied: the rejected out-of-range identifier must not appear
        # in the interface's running-config.
        running = dut.cmd('show running-config interface {}'.format(port.name))
        rejected = ('% Invalid input detected' in output
                    or 'Invalid input' in output
                    or '% Unknown command' in output
                    or 'out of range' in output.lower())
        applied = 'civic-location identifier {}'.format(badIndex) in running
        if rejected and not applied:
            self.passed('out-of-range TLV index {} rejected by the CLI and not present in running-config'.format(badIndex))
        elif not rejected:
            self.failed('out-of-range TLV index {} was accepted without a diagnostic; CLI output: {}'.format(badIndex, output.strip()))
        else:
            self.failed('out-of-range TLV index {} was rejected but a change was still applied to running-config'.format(badIndex))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        pass


class TestCase_32(ATTestCase.TestCase):
    testCaseDesc = "After each of the three rejected keyword attempts, re-read the port's TLV selection."
    testCaseRef = 'AWPTCM-T44297'
    testCaseMethod = "After each of the three rejected keyword attempts, re-read the port's TLV selection. | verify: `show lldp interface <port>` shows the previously configured TLV selection unchanged after every rejected attempt."

    def main(self):
        # ART 1331_past_issues/test-1331.1001.py lines 760-784
        self.log("STEP 32: After each of the three rejected keyword attempts, re-read the port's TLV selection.")
        dutA = self.testSet.dutA
        port = self.testSet.dut.portA
        name = port.name

        # Snapshot the configured TLV selection before driving any rejected keywords.
        dutA.mode('#')
        baseline = dutA.cmd('show lldp interface {}'.format(name))

        # Three keyword attempts the CLI rejects; each must leave the TLV selection untouched.
        rejected_keywords = ['bogus-tlv', 'not-a-tlv', 'invalid-keyword']
        reads = []
        for keyword in rejected_keywords:
            dutA.mode(')#')
            dutA.cmd('interface {}'.format(name))
            dutA.cmd('lldp med-tlv-select {}'.format(keyword))
            dutA.mode('#')
            reads.append((keyword, dutA.cmd('show lldp interface {}'.format(name))))

        output = reads[-1][1]
        self.log('OBSERVED: {}'.format(output))

        changed = [kw for kw, out in reads if out.strip() != baseline.strip()]
        if not changed:
            self.passed('show lldp interface {} TLV selection unchanged after all three rejected keyword attempts'.format(name))
        else:
            self.failed('show lldp interface {} TLV selection changed after rejected attempt(s): {}'.format(name, ', '.join(changed)))

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        dutA = self.testSet.dutA
        dutA.mode('#')


class TestCase_33(ATTestCase.TestCase):
    testCaseDesc = 'Disable LLDP on a spare port (`no lldp transmit`/`no lldp receive` or port-level disable), apply a set of TLV selections while it is disabled, confirm they are accepted and stored, then enable LLDP transmission on that port and capture LLDPDUs.'
    testCaseRef = 'AWPTCM-T44297'
